Framework: common
Heading: Access Session-Scoped Beans
Document Path: v25.3/building-apps/testing/browserless/setup-spring-boot.md (use get_full_document to get complete context)
----

A Spring test field is injected before the browserless Vaadin session exists.
If a test needs an application bean with `@VaadinSessionScope`, inject an `ObjectProvider` and resolve the bean after environment setup:  
`CartViewSessionTest.java`  

```java
import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.ObjectProvider;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import com.vaadin.browserless.SpringBrowserlessTest;

@SpringBootTest
class CartViewSessionTest extends SpringBrowserlessTest {

    @Autowired
    private ObjectProvider<Cart> cartProvider;

    @Test
    void addItem_cartContainsItem() {
        CartView view = navigate(CartView.class);
        Cart cart = cartProvider.getObject();

        test(view.addButton).click();

        Assertions.assertEquals(1, cart.getItems().size());
    }
}
