+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.data.value.ValueChangeMode;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.PageTitle;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.RouterLink;
+
+@Route("contact")
+@PageTitle("Contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+
+    private static final int MAX_MESSAGE_LENGTH = 500;
+    private static final Pattern EMAIL = Pattern.compile("[^@\\s]+@[^@\\s]+\\.[^@\\s]+");
+
+    private final ContactMessageService service;
+
+    private final TextField name = new TextField("Name");
+    private final EmailField email = new EmailField("Email");
+    private final TextField phone = new TextField("Phone");
+    private final TextArea message = new TextArea("Message");
+    private final Button send = new Button("Send", e -> submit());
+
+    private final Grid<ContactMessage> grid = new Grid<>();
+
+    private final Dialog leaveDialog = new Dialog();
+    private BeforeLeaveEvent.ContinueNavigationAction pendingNavigation;
+
+    public ContactView(ContactMessageService service) {
+        this.service = service;
+
+        setPadding(true);
+
+        for (AbstractField<?, String> field : inputs()) {
+            field.addValueChangeListener(e -> send.setEnabled(true));
+        }
+        name.setValueChangeMode(ValueChangeMode.EAGER);
+        email.setValueChangeMode(ValueChangeMode.EAGER);
+        phone.setValueChangeMode(ValueChangeMode.EAGER);
+        message.setValueChangeMode(ValueChangeMode.EAGER);
+        message.setWidthFull();
+
+        // Enter submits from the single-line fields; in the message it still inserts a line break
+        for (AbstractField<?, String> field : List.of(name, email, phone)) {
+            Shortcuts.addShortcutListener(field, this::submitIfEnabled, Key.ENTER);
+        }
+
+        FormLayout form = new FormLayout(name, email, phone, message);
+        form.setResponsiveSteps(new FormLayout.ResponsiveStep("0", 2));
+        form.setColspan(message, 2);
+
+        send.addThemeVariants(ButtonVariant.LUMO_PRIMARY);
+
+        grid.addColumn(ContactMessage::name).setHeader("Name").setAutoWidth(true);
+        grid.addColumn(ContactMessage::email).setHeader("Email").setAutoWidth(true);
+        grid.addColumn(ContactMessage::phone).setHeader("Phone").setAutoWidth(true);
+        grid.addColumn(ContactMessage::message).setHeader("Message").setFlexGrow(1);
+        grid.setItems(service.findAll());
+        grid.setWidthFull();
+
+        setupLeaveDialog();
+
+        add(
+                new H1("Contact"),
+                new RouterLink("About", AboutView.class),
+                form,
+                new HorizontalLayout(send),
+                grid,
+                leaveDialog);
+    }
+
+    private void setupLeaveDialog() {
+        leaveDialog.setHeaderTitle("Discard your message?");
+        leaveDialog.add(new Paragraph("The form has unsent input. Leaving now will lose it."));
+
+        Button keepEditing = new Button("Keep editing", e -> {
+            BeforeLeaveEvent.ContinueNavigationAction action = pendingNavigation;
+            pendingNavigation = null;
+            leaveDialog.close();
+            if (action != null) {
+                action.cancel();
+            }
+        });
+        Button discard = new Button("Discard", e -> {
+            BeforeLeaveEvent.ContinueNavigationAction action = pendingNavigation;
+            pendingNavigation = null;
+            leaveDialog.close();
+            if (action != null) {
+                action.proceed();
+            }
+        });
+        discard.addThemeVariants(ButtonVariant.LUMO_ERROR);
+        leaveDialog.getFooter().add(keepEditing, discard);
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (!hasInput()) {
+            return;
+        }
+        event.postpone();
+        pendingNavigation = event.getContinueNavigationAction();
+        leaveDialog.open();
+    }
+
+    private List<AbstractField<?, String>> inputs() {
+        return List.of(name, email, phone, message);
+    }
+
+    private boolean hasInput() {
+        return inputs().stream().anyMatch(field -> !field.getValue().isEmpty());
+    }
+
+    private void submitIfEnabled() {
+        if (send.isEnabled()) {
+            submit();
+        }
+    }
+
+    private void submit() {
+        if (!validate()) {
+            return;
+        }
+
+        service.add(new ContactMessage(
+                name.getValue().trim(),
+                email.getValue().trim(),
+                phone.getValue().trim(),
+                message.getValue().trim()));
+        grid.setItems(service.findAll());
+
+        Notification.show("Message sent");
+
+        clearForm();
+        // Clearing fires the value listeners, which enable Send again; it stays disabled until the next edit
+        send.setEnabled(false);
+    }
+
+    private boolean validate() {
+        String nameValue = name.getValue().trim();
+        String emailValue = email.getValue().trim();
+        String phoneValue = phone.getValue().trim();
+        String messageValue = message.getValue();
+
+        String nameError = nameValue.isEmpty() ? "Name is required" : null;
+
+        String emailError = null;
+        if (!emailValue.isEmpty() && !EMAIL.matcher(emailValue).matches()) {
+            emailError = "Enter a valid e-mail address";
+        } else if (emailValue.isEmpty() && phoneValue.isEmpty()) {
+            emailError = "Give an e-mail address or a phone number";
+        }
+
+        String messageError = null;
+        if (messageValue.isBlank()) {
+            messageError = "Message is required";
+        } else if (messageValue.codePointCount(0, messageValue.length()) > MAX_MESSAGE_LENGTH) {
+            messageError = "Message must be at most " + MAX_MESSAGE_LENGTH + " characters";
+        }
+
+        mark(name, nameError);
+        mark(email, emailError);
+        mark(message, messageError);
+
+        return nameError == null && emailError == null && messageError == null;
+    }
+
+    private static void mark(HasValidation field, String error) {
+        field.setInvalid(error != null);
+        field.setErrorMessage(error);
+    }
+
+    private void clearForm() {
+        for (AbstractField<?, String> field : inputs()) {
+            field.setValue("");
+        }
+        name.setInvalid(false);
+        email.setInvalid(false);
+        phone.setInvalid(false);
+        message.setInvalid(false);
+    }
+}
