+import org.springframework.test.annotation.DirtiesContext;
+import org.springframework.test.annotation.DirtiesContext.ClassMode;
+
+import com.microsoft.playwright.Browser;
+import com.microsoft.playwright.Locator;
+import com.microsoft.playwright.Page;
+import com.microsoft.playwright.Playwright;
+import com.microsoft.playwright.options.AriaRole;
+
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+@DirtiesContext(classMode = ClassMode.AFTER_CLASS)
+class ContactViewBrowserTest {
+
+    @LocalServerPort
+    int port;
+
+    @Test
+    void sendWithEnter_thenLeaveWithUnsavedInput() {
+        try (Playwright playwright = Playwright.create();
+             Browser browser = playwright.chromium().launch()) {
+            Page page = browser.newPage();
+            page.navigate("http://localhost:" + port + "/contact");
+            assertThat(page.getByRole(AriaRole.HEADING, new Page.GetByRoleOptions().setName("Contact"))).isVisible();
+
+            page.getByLabel("Name").fill("Ada");
+            page.getByLabel("Phone").fill("+358 40 123");
+            page.getByLabel("Message", new Page.GetByLabelOptions().setExact(true)).fill("Hello from the browser");
+            page.getByLabel("Phone").press("Enter");
+
+            assertThat(page.getByText("Message sent")).isVisible();
+            assertThat(page.locator("vaadin-grid").getByText("Hello from the browser")).isVisible();
+            assertThat(page.getByLabel("Name")).isEmpty();
+            assertThat(page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Send"))).isDisabled();
+
+            page.getByLabel("Name").fill("Bob");
+            assertThat(page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Send"))).isEnabled();
+
+            page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("About")).click();
+            Locator dialog = page.locator("vaadin-dialog-overlay[opened]");
+            assertThat(dialog).hasCount(1);
+            page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Keep editing")).click();
+            assertThat(dialog).hasCount(0);
+            assertThat(page.getByLabel("Name")).hasValue("Bob");
+
+            page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("About")).click();
+            page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Discard")).click();
+            assertThat(page.getByRole(AriaRole.HEADING, new Page.GetByRoleOptions().setName("About"))).isVisible();
+        }
+    }
+}
