+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+
+// Each test gets a fresh service, so the messages list starts empty
+@SpringBootTest
+@DirtiesContext(classMode = ClassMode.AFTER_EACH_TEST_METHOD)
+class ContactViewTest extends SpringBrowserlessTest {
+
+    @Test
+    void untouchedForm_sendIsEnabled_fieldsEmpty() {
+        navigate(ContactView.class);
+
+        assertEquals("", name().getValue());
+        assertEquals("", email().getValue());
+        assertEquals("", phone().getValue());
+        assertEquals("", message().getValue());
+        assertTrue(send().isEnabled());
+    }
+
+    @Test
+    void emptySubmit_marksEachRequiredField_sendsNothing() {
+        navigate(ContactView.class);
+
+        test(send()).click();
+
+        assertEquals("Name is required", name().getErrorMessage());
+        assertTrue(name().isInvalid());
+        assertEquals("Give an e-mail address or a phone number", email().getErrorMessage());
+        assertTrue(email().isInvalid());
+        assertEquals("Message is required", message().getErrorMessage());
+        assertTrue(message().isInvalid());
+        assertFalse($(Notification.class).exists());
+        assertTrue(grid().getGenericDataView().getItems().findAny().isEmpty());
+    }
+
+    @Test
+    void invalidEmail_marksEmail_keepsTypedInput() {
+        navigate(ContactView.class);
+        test(name()).setValue("Ada");
+        test(email()).setValue("not-an-address");
+        test(message()).setValue("Hello");
+
+        test(send()).click();
+
+        assertEquals("Enter a valid e-mail address", email().getErrorMessage());
+        assertTrue(email().isInvalid());
+        assertFalse(name().isInvalid());
+        assertEquals("Ada", name().getValue());
+        assertEquals("not-an-address", email().getValue());
+    }
+
+    @Test
+    void messageTooLong_marksMessage() {
+        navigate(ContactView.class);
+        test(name()).setValue("Ada");
+        test(phone()).setValue("123");
+        test(message()).setValue("x".repeat(501));
+
+        test(send()).click();
+
+        assertEquals("Message must be at most 500 characters", message().getErrorMessage());
+        assertTrue(message().isInvalid());
+    }
+
+    @Test
+    void phoneOnly_sends_clearsForm_disablesSend() {
+        navigate(ContactView.class);
+        test(name()).setValue("Ada");
+        test(phone()).setValue("+358 40 123");
+        test(message()).setValue("Hello there");
+
+        test(send()).click();
+
+        Notification notification = $(Notification.class).single();
+        assertTrue(test(notification).getText().contains("Message sent"));
+        ContactMessage first = firstRow();
+        assertEquals("Ada", first.name());
+        assertEquals("Hello there", first.message());
+        assertEquals("", name().getValue());
+        assertEquals("", phone().getValue());
+        assertEquals("", message().getValue());
+        assertFalse(send().isEnabled());
+
+        test(name()).setValue("Bob");
+        assertTrue(send().isEnabled());
+    }
+
+    @Test
+    void enterInNameField_sendsWhenValid() {
+        navigate(ContactView.class);
+        test(name()).setValue("Ada");
+        test(email()).setValue("ada@example.com");
+        test(message()).setValue("Hi");
+
+        fireShortcut(Key.ENTER);
+
+        assertEquals("Ada", firstRow().name());
+        assertEquals("ada@example.com", firstRow().email());
+    }
+
+    @Test
+    void messagesPersistAcrossVisits() {
+        navigate(ContactView.class);
+        test(name()).setValue("Persisted");
+        test(phone()).setValue("1");
+        test(message()).setValue("Kept");
+        test(send()).click();
+
+        navigate(ContactView.class);
+
+        assertEquals("Persisted", firstRow().name());
+    }
+
+    @Test
+    void leaveWithInput_asksFirst_keepEditingStaysOnView() {
+        navigate(ContactView.class);
+        test(name()).setValue("Ada");
+
+        UI.getCurrent().navigate(AboutView.class);
+
+        Dialog dialog = $(Dialog.class).single();
+        assertTrue(dialog.isOpened());
+        assertFalse($(AboutView.class).exists());
+        test(button(dialog, "Keep editing")).click();
+        assertFalse(dialog.isOpened());
+        assertEquals("Ada", name().getValue());
+    }
+
+    @Test
+    void leaveWithInput_discard_navigatesToAbout() {
+        navigate(ContactView.class);
+        test(name()).setValue("Ada");
+
+        UI.getCurrent().navigate(AboutView.class);
+        Dialog dialog = $(Dialog.class).single();
+        test(button(dialog, "Discard")).click();
+
+        assertFalse(dialog.isOpened());
+        assertTrue($(AboutView.class).exists());
+    }
+
+    @Test
+    void leaveAgainAfterKeepEditing_dialogOpensAgain() {
+        navigate(ContactView.class);
+        test(name()).setValue("Ada");
+        UI.getCurrent().navigate(AboutView.class);
+        test(button($(Dialog.class).single(), "Keep editing")).click();
+
+        UI.getCurrent().navigate(AboutView.class);
+
+        assertTrue($(Dialog.class).single().isOpened());
+        assertFalse($(AboutView.class).exists());
+    }
+
+    @Test
+    void leaveWithEmptyForm_noDialog() {
+        navigate(ContactView.class);
+
+        UI.getCurrent().navigate(AboutView.class);
+
+        assertFalse($(Dialog.class).exists());
+        assertTrue($(AboutView.class).exists());
+    }
+
+    private ContactMessage firstRow() {
+        return grid().getGenericDataView().getItems().findFirst().orElseThrow();
+    }
+
+    @SuppressWarnings("unchecked")
+    private Grid<ContactMessage> grid() {
+        return (Grid<ContactMessage>) $(Grid.class).single();
+    }
+
+    private TextField name() {
+        return $(TextField.class).withLabel("Name").single();
+    }
+
+    private TextField phone() {
+        return $(TextField.class).withLabel("Phone").single();
+    }
+
+    private EmailField email() {
+        return $(EmailField.class).withLabel("Email").single();
+    }
+
+    private TextArea message() {
+        return $(TextArea.class).withLabel("Message").single();
+    }
+
+    private Button send() {
+        return $(Button.class).withText("Send").single();
+    }
+
+    private Button button(Dialog dialog, String text) {
+        return $(Button.class, dialog).withText(text).single();
+    }
+}
